candidate.declaration:
FUNCTION_BLOCK FB_Task
VAR_INPUT
    Demand : BOOL;
    FaultA : BOOL;
    FaultB : BOOL;
END_VAR
VAR_OUTPUT
    PumpA : BOOL := FALSE;
    PumpB : BOOL := FALSE;
    LeadA : BOOL := TRUE;
END_VAR
VAR
    previous_demand : BOOL := FALSE;
    episode_served : BOOL := FALSE;
END_VAR

candidate.implementation:
PumpA := FALSE;
PumpB := FALSE;

IF Demand THEN
    IF LeadA AND NOT FaultA THEN
        PumpA := TRUE;
    ELSIF (NOT LeadA) AND NOT FaultB THEN
        PumpB := TRUE;
    ELSIF NOT FaultA THEN
        PumpA := TRUE;
    ELSIF NOT FaultB THEN
        PumpB := TRUE;
    END_IF;

    IF PumpA OR PumpB THEN
        episode_served := TRUE;
    END_IF;
ELSE
    IF previous_demand AND episode_served THEN
        LeadA := NOT LeadA;
    END_IF;
    episode_served := FALSE;
END_IF;

previous_demand := Demand;
